"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["31339"],{71987(e){e.exports=JSON.parse('{"id":"F438","slug":"carry-trade-return","name":"Carry Trade Return and Break-Even","subject":"International Finance","section":"Global Finance","topic":"Carry trade","level":"Intermediate","aliases":["carry trade","funding currency","currency crash risk","leveraged carry"],"formula":{"latex":"R=(1+i_{h})(1+\\\\Delta s)-(1+i_{l}),\\\\quad \\\\Delta s^{*}=\\\\frac{1+i_{l}}{1+i_{h}}-1","also":[],"text":"Return per unit borrowed = (1 + high-yield rate) x (1 + change in the high-yield currency) - (1 + funding rate); Break-even currency move = (1 + funding rate) / (1 + high rate) - 1; Levered return = leverage x return per unit"},"symbols":[{"symbol":"i_h","meaning":"Interest rate in the currency you invest in","unit":"per year"},{"symbol":"i_l","meaning":"Interest rate in the funding currency you borrow","unit":"per year"},{"symbol":"Delta s","meaning":"Change in the invested currency against the funding currency","unit":"percent"},{"symbol":"Leverage","meaning":"Position size per unit of own capital","unit":"number"}],"when_to_use":"Use it to size the risk of a carry trade: borrow in a low-rate currency and lend in a high-rate one. The trade earns the rate gap if the exchange rate holds, and loses if the high-yield currency falls by more than the break-even. Returns are small and steady, with rare sharp losses when the funding currency surges in a crisis, and leverage multiplies both sides.","worked_example":{"problem":"Borrow yen at 0.5% and invest in a currency yielding 4.5%. The position is 5 times capital. The invested currency falls 3% against the yen over the year.","inputs":{"ih":4.5,"il":0.5,"lv":5,"mv":-3},"steps":[{"label":"Break-even currency move = (1 + il) / (1 + ih) - 1","working":"(1+0.005) / (1+0.045)-1","value":"-3.83%"},{"label":"Return per unit borrowed","working":"(1+0.045) x (1+-0.03)-(1+0.005)","value":"0.87%"},{"label":"Levered return on capital","working":"5 x 0.00865","value":"4.33%"},{"label":"Carry with no currency move","working":"0.045-0.005","value":"4.00%"},{"label":"Levered carry","working":"5 x 0.04","value":"20.00%"},{"label":"Size of the fall the carry can absorb","working":"--0.0382775","value":"3.83%"}],"answer":"The break-even fall in the invested currency is -3.83%. A move of -3% gives a return of 0.87% per unit borrowed, or 4.33% on capital at 5 times leverage. Without any move the carry alone earns 4.00%, or 20.00% levered. The currency can lose 3.83% before the trade loses money."},"calculator":{"available":true,"inputs":[{"id":"ih","label":"High-yield currency rate","unit":"%","type":"number","default":4.5,"hint":""},{"id":"il","label":"Funding currency rate","unit":"%","type":"number","default":0.5,"hint":""},{"id":"lv","label":"Leverage","unit":"","type":"number","default":5,"hint":""},{"id":"mv","label":"Change in the invested currency","unit":"%","type":"number","default":-3,"hint":""}],"checks":[{"expr":"lv>0","message":"Leverage must be above zero."}],"steps":[{"id":"be","label":"Break-even currency move = (1 + il) / (1 + ih) - 1","expr":"(1+il)/(1+ih)-1","format":"pct2"},{"id":"r","label":"Return per unit borrowed","expr":"(1+ih)*(1+mv)-(1+il)","format":"pct2"},{"id":"rl","label":"Levered return on capital","expr":"lv*r","format":"pct2"},{"id":"carry","label":"Carry with no currency move","expr":"ih-il","format":"pct2"},{"id":"carryl","label":"Levered carry","expr":"lv*carry","format":"pct2"},{"id":"be_","label":"Size of the fall the carry can absorb","expr":"-be","format":"pct2"}],"results":["be","r","rl"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"be":-0.03827751196172258,"r":8.650000000000047e-3,"rl":0.04325000000000023,"carry":0.04,"carryl":0.2,"be_":0.03827751196172258}},"finder":{"finds":"Whether a currency carry trade pays for its risk","needs":"Both rates, leverage, a currency move"},"related":[{"slug":"uncovered-interest-parity","name":"Uncovered Interest Parity and Unhedged Return"},{"slug":"fx-forward-points","name":"Forward Exchange Rate and Forward Points"},{"slug":"sharpe-ratio","name":"Sharpe Ratio"}],"related_ids":["F435","F433","F245"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>R</mi><mo>=</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><msub><mi>i</mi><mi>h</mi></msub><mo stretchy=\\"false\\">)</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi mathvariant=\\"normal\\">\u0394</mi><mi>s</mi><mo stretchy=\\"false\\">)</mo><mo>\u2212</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><msub><mi>i</mi><mi>l</mi></msub><mo stretchy=\\"false\\">)</mo><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi mathvariant=\\"normal\\">\u0394</mi><msup><mi>s</mi><mo lspace=\\"0em\\" rspace=\\"0em\\">\u2217</mo></msup><mo>=</mo><mfrac><mrow><mn>1</mn><mo>+</mo><msub><mi>i</mi><mi>l</mi></msub></mrow><mrow><mn>1</mn><mo>+</mo><msub><mi>i</mi><mi>h</mi></msub></mrow></mfrac><mo>\u2212</mo><mn>1</mn></mrow><annotation encoding=\\"application/x-tex\\">R=(1+i_{h})(1+\\\\Delta s)-(1+i_{l}),\\\\quad \\\\Delta s^{*}=\\\\frac{1+i_{l}}{1+i_{h}}-1</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"carhart-model","name":"Carhart Four-Factor Model Return"},"next":{"slug":"cash-conversion-cycle","name":"Cash Conversion Cycle"},"lesson":null,"total":522}')}}]);